const body = $input.first().json.body || $input.first().json;
const message = (body.message || '').trim();
const userName = body.userName || 'User';
const conversationId = body.conversationId || 'default';
const callbackUrl = body.callbackUrl || '';
const attachments = body.attachments || [];

const parts = [];
if (message) parts.push(message);
for (const att of attachments) {
  if (att.name && att.content) {
    parts.push(`\n[Attached file: ${att.name}, ${Math.round((att.sizeBytes || 0) / 1024)} KB]`);
  } else if (att.name) {
    parts.push(`\n[File attached (could not be downloaded): ${att.name}]`);
  }
}
const userMessage = parts.join('\n') || `Hello from ${userName}`;

const userId = body.userId || body.from?.id || '';
const aadObjectId = body.aadObjectId || body.from?.aadObjectId || '';
return [{ json: { userMessage, rawMessage: message, conversationId, callbackUrl, userName, userId, aadObjectId, attachments } }];

const prep = $input.first().json;
const siteUrl = $env.SHAREPOINT_SITE_URL || '';
const results = [];
for (const att of prep.attachments || []) {
  if (!att.content) continue;
  const fileName = att.name || 'attachment';
  const binary = await this.helpers.prepareBinaryData(
    Buffer.from(att.content, 'base64'),
    fileName,
    att.contentType || 'application/octet-stream'
  );
  results.push({
    json: {
      conversationId: prep.conversationId,
      userName: prep.userName,
      fileName,
      contentType: att.contentType || 'application/octet-stream',
      query: `Upload the file "${fileName}" from binary field "data" into the Transcripts document library at site ${siteUrl} under folder "${prep.conversationId}". The binary content is already attached to this item.`
    },
    binary: { data: binary }
  });
}
return results.length ? results : [{ json: { conversationId: prep.conversationId, userName: prep.userName, fileName: '', contentType: '', query: 'No file to upload. Return immediately.' } }];

const agentOutput = ($input.first().json.output || '').trim() || 'I could not generate a response. Please try again.';
const prep = $('Prepare Input').item.json;
return [{ json: { conversationId: prep.conversationId, reply: agentOutput, callbackUrl: prep.callbackUrl } }];
